-- «usd_rate» — the Central Bank's dollar rate, one row per day (2026-10-28).
-- cbu.uz stopped answering DigitalOcean's network (from 26.10 at the latest:
-- a connect timeout from the web container, 200 in 0.1 s from Tashkent), and
-- every rate lived in the web process alone, so a deploy forgot them all:
-- «Kunlar boʻyicha» printed no soʻm spend, CPL, CPQL, CPO or ROAS, «RNP
-- jadvali» no CAC or ROMI for October. CbuUsdRates now keeps each answer here
-- and reads it before asking the bank.
--
-- Additive only: one new table. The rows below are the bank's own answers
-- for 2025-01-01 … 2026-10-28, read from cbu.uz
-- (/uz/arkhiv-kursov-valyut/json/USD/<day>/) from Tashkent on 2026-10-28 —
-- a weekend or holiday holds the rate in force that day, as the bank answers
-- it. UZS per USD in micro units, as marketing_snapshot.usdRateMicro.

-- CreateTable
CREATE TABLE "usd_rate" (
    "day" DATE NOT NULL,
    "rateMicro" BIGINT NOT NULL,
    "source" TEXT NOT NULL,
    "fetchedAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,

    CONSTRAINT "usd_rate_pkey" PRIMARY KEY ("day")
);

ON CONFLICT ("day") DO NOTHING;
